mapper.select:
select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wdr.warehouse_id in

        #{id}



    and wdr.affirm_time between #{startTime} and #{endTime}

and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr
    join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
    join wms_inventory wi on wi.id = info.inventory_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wi.shelf_id in

        #{id}



    and wdr.affirm_time between #{startTime} and #{endTime}

and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr
join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
join wms_inventory wi on wi.id = info.inventory_id
where wdr.del_flag = 0 and info.del_flag = 0







    and wdr.affirm_time between #{startTime} and #{endTime}


    and info.material_id in

        #{id}


and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id,info.quantity as quantity,wdr.affirm_time,wi.material_code from wms_delivery_receipt wdr join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id join wms_inventory wi on wi.id = info.inventory_id where wdr.del_flag = 0 and info.del_flag = 0
and wdr.affirm_time between #{startTime} and #{endTime}
and wdr.`status` in(1,2,3,5)

SELECT SUM(quantity) FROM wms_delivery_receipt a LEFT JOIN wms_delivery_receipt_info b ON b.delivery_receipt_id = a.id where a.type = 1800831413027946496 and a.warehouse_id in
#{id}
and a.affirm_time between #{firstDay} and #{lastDay}

select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr
join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
join wms_inventory wi on wi.id = info.inventory_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wdr.warehouse_id = #{warehouseId}


    and wdr.affirm_time between #{startTime} and #{endTime}


    and info.material_id in

        #{id}


and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id,
count(DISTINCT wdr.id ) AS count  from wms_delivery_receipt wdr
join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
join wms_inventory wi on wi.id = info.inventory_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wdr.warehouse_id = #{warehouseId}


    and wdr.affirm_time between #{startTime} and #{endTime}


    and info.material_id in

        #{id}


and wdr.`status` in(1,2,3,5)
group by 	info.material_id;

select c.* , m.affirm_time as create_time from wms_delivery_receipt m join wms_delivery_receipt_info c where m.del_flag = 0 and c.del_flag = 0 and m.id = c.delivery_receipt_id and c.associated_no is not null and m.affirm_time >= #{start} and m.affirm_time < #{end}
and c.material_id in
#{id}

select productionLineName AS productionLineName, any_value(productionLineId) AS productionLineId, warehouseId, type, any_value(materialName) AS materialName, materialId, status, COUNT(*) AS caseNum, sum(quantity) AS totalQuantity, classes, group_concat(case_no ORDER BY case_no SEPARATOR ', ') as caseNo from ( select a.out_time AS out_time, a.product_line_name AS productionLineName, a.product_line_id AS productionLineId, a.warehouse_id AS warehouseId, a.code AS code, a.type AS type, CASE WHEN a.status = 0 THEN '已创建' WHEN a.status = 1 THEN '已确认' WHEN a.status = 2 THEN '已同步' WHEN a.status = 5 THEN '已冲销' END AS status, CASE WHEN TIME(a.out_time) BETWEEN '20:00:00' AND '23:59:59' OR TIME(a.out_time) BETWEEN '00:00:00' AND '08:00:00' THEN '夜班' WHEN TIME(a.out_time) BETWEEN '08:00:00' AND '20:00:00' THEN '白班' END AS classes, a.affirm_name AS affirm_name, a.affirm_time AS affirm_time, a.create_name AS create_name, a.create_time AS create_time, d.material_name AS materialName, d.material_id AS materialId, d.case_no AS case_no, c.quantity AS quantity, a.note as note from wms_delivery_receipt a join wms_delivery_receipt_info c on c.delivery_receipt_id = a.id join wms_inventory d on c.inventory_id = d.id where a.del_flag = 0 and c.del_flag = 0 -- and a.type = 1582296769061031936
AND (a.type = 1582296769061031936 or a.type = 1582297407643815936)
AND a.type = #{dto.type}
AND a.out_time >= #{dto.startTime} AND a.out_time < #{dto.endTime}
AND a.status = #{dto.status}
AND a.warehouse_id = #{dto.warehouseId}
AND a.product_line_name = #{dto.productionLineName}
) as newlist group by productionLineName, warehouseId, type, materialId, status, classes ORDER BY type, CASE WHEN productionLineName IS NULL THEN 9 WHEN productionLineName LIKE '深加工一产线' THEN 1 WHEN productionLineName LIKE '深加工二产线' THEN 2 WHEN productionLineName LIKE '深加工三产线' THEN 3 WHEN productionLineName LIKE '深加工四产线' THEN 4 WHEN productionLineName LIKE '深加工五产线' THEN 5 WHEN productionLineName LIKE '深加工六产线' THEN 6 WHEN productionLineName LIKE '深加工七产线' THEN 7 WHEN productionLineName LIKE '深加工八产线' THEN 8 ELSE 9 END, classes DESC

select a.out_time AS outTime, -- a.product_line_name AS productionLineName, -- a.product_line_id AS productionLineId, a.warehouse_id AS warehouseId, a.code AS code, a.type AS type, a.status AS status, CASE WHEN TIME(a.out_time) BETWEEN '20:00:00' AND '23:59:59' OR TIME(a.out_time) BETWEEN '00:00:00' AND '08:00:00' THEN '夜班' WHEN TIME(a.out_time) BETWEEN '08:00:00' AND '20:00:00' THEN '白班' END AS classes, a.affirm_name AS affirm_name, a.affirm_time AS affirm_time, a.create_name AS create_name, a.create_time AS create_time, d.material_name AS materialName, d.material_id AS materialId, d.case_no AS caseNo, c.quantity AS quantity, a.note as note, d.shelf_name AS shelfName from wms_delivery_receipt a join wms_delivery_receipt_info c on c.delivery_receipt_id = a.id join wms_inventory d on c.inventory_id = d.id where a.type = 1582296769061031936 and a.del_flag = 0 and c.del_flag = 0
and d.case_no in
#{caseNo}
